// The compiled knowledge base as one value (SPEC §5). The JSON files in ./data are generated by
// kb-src/build_kb.py; this module only assembles them. It imports nothing else from src/, so both the public API
// (./index.ts) and the name matcher (./normalize.ts) can depend on it without an import cycle.

import type {
  BeersRule,
  CascadeRule,
  FridClass,
  KbClass,
  KbCombo,
  KbDrug,
  KbSource,
  KnowledgeBase,
  MonitoringRule,
} from "./types";
import sources from "./data/sources.json";
import classes from "./data/classes.json";
import drugs from "./data/drugs.json";
import combos from "./data/combos.json";
import beers from "./data/beers.json";
import cascades from "./data/cascades.json";
import frids from "./data/frids.json";
import monitoring from "./data/monitoring.json";
import meta from "./data/meta.json";

/** How the name matcher picks a route- or dose-specific entry (see V() in kb-src/kb/drugs_src.py). */
export interface KbDrugVariant {
  /** The base ingredient id typed names resolve to first ("diclofenac"). */
  of: string;
  /** Words in the typed name that select this entry ("gel", "eye drops"). */
  words?: string[];
  /** Words that send this entry back to the base ("tablet"; "#mg" = any "<number> mg"). */
  baseWords?: string[];
  /** A typed strength at or below this (mg) selects this entry ("doxepin 3 mg"). */
  maxDoseMg?: number;
}

/** Optional fields the compiled drugs carry beyond the typed contract. */
export type KbDrugCompiled = KbDrug & { variant?: KbDrugVariant };

/** Optional Beers-rule qualifiers the compiled rules carry (read by src/engine/meds/rules/beers.ts). */
export type BeersRuleCompiled = BeersRule & {
  reasonKeywords?: string[];
  excludeReasonKeywords?: string[];
  excludeDrugs?: string[];
  maxDaysSinceStart?: number;
  sex?: "female" | "male";
  sourceRef?: string;
};

// The JSON imports are typed from their contents; the casts name the contract they were built to (kb.test.ts
// checks the shape of every record at test time).
export const KB: KnowledgeBase = {
  version: meta.version,
  sources: sources as unknown as KbSource[],
  classes: classes as unknown as KbClass[],
  drugs: drugs as unknown as KbDrugCompiled[],
  combos: combos as unknown as KbCombo[],
  beers: beers as unknown as BeersRuleCompiled[],
  cascades: cascades as unknown as CascadeRule[],
  frids: frids as unknown as FridClass[],
  monitoring: monitoring as unknown as MonitoringRule[],
  acbThresholds: meta.acbThresholds,
  coverageNote: meta.coverageNote,
};

/** Criteria the KB deliberately does not encode, with the reason (for the How-it-works page). */
export const KB_NOT_ENCODED: { criterion: string; reason: string }[] = meta.notEncoded;
